package org.solarelevation.alarm;
import android.app.job.*;
import android.content.*;
import android.location.*;
import android.os.*;
import android.util.Log;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
public final class SolarAlarmMaintenanceJob extends JobService {
public static final String SOURCE_ID="SolarAlarmMaintenanceJob_v20261022T025042Z";
private static final int JOB_ID=0x53414c;
private static final long PERIOD=86400000L,FLEX=7200000L;
private static final class Run {volatile boolean stopped;volatile CancellationSignal signal;Thread thread;}
private volatile Run active;
public static boolean scheduled(Context c){try{JobScheduler jobs=(JobScheduler)c.getSystemService(Context.JOB_SCHEDULER_SERVICE);return jobs!=null&&jobs.getPendingJob(JOB_ID)!=null;}catch(Exception ex){return false;}}
public static void ensure(Context c){JobScheduler jobs=(JobScheduler)c.getSystemService(Context.JOB_SCHEDULER_SERVICE);if(jobs==null)return;try{if(!SolarAlarmLocation.background(c)){jobs.cancel(JOB_ID);return;}if(jobs.getPendingJob(JOB_ID)!=null)return;JobInfo info=new JobInfo.Builder(JOB_ID,new ComponentName(c,SolarAlarmMaintenanceJob.class)).setPeriodic(PERIOD,FLEX).setPersisted(true).build();if(jobs.schedule(info)!=JobScheduler.RESULT_SUCCESS)Log.w("SolarAlarm","Daily background GPS job not scheduled");}catch(Exception ex){Log.e("SolarAlarm","Daily background GPS job setup failed",ex);}}
public boolean onStartJob(JobParameters p){Run r=new Run();active=r;r.thread=new Thread(()->{boolean retry=false;SharedPreferences prefs=getSharedPreferences("maintenance",0);prefs.edit().putLong("gps_attempt",System.currentTimeMillis()).putString("gps_status","Requesting a fresh position").apply();try{if(!SolarAlarmLocation.background(this)){prefs.edit().putString("gps_status","Background location permission missing").apply();return;}LocationManager manager=(LocationManager)getSystemService(LOCATION_SERVICE);Location fix=null;if(checkSelfPermission(android.Manifest.permission.ACCESS_FINE_LOCATION)==android.content.pm.PackageManager.PERMISSION_GRANTED)fix=request(manager,LocationManager.GPS_PROVIDER,45000L,r);if(fix==null&&!r.stopped)fix=request(manager,LocationManager.NETWORK_PROVIDER,20000L,r);if(r.stopped)return;if(fix==null){prefs.edit().putString("gps_status","No fresh location; existing alarms preserved").apply();return;}int saved=SolarAlarmLocation.save(this,fix);if(saved==0){prefs.edit().putString("gps_status","Location rejected as stale or invalid; alarms preserved").apply();return;}if(saved==2){SolarAlarmLocation.rearm(this);if(r.stopped||Thread.currentThread().isInterrupted()){retry=true;return;}}prefs.edit().putLong("gps_success",System.currentTimeMillis()).putString("gps_status",saved==2?"Fresh GPS/network fix; alarms recalculated":"Fresh GPS/network fix; position unchanged").apply();}catch(InterruptedException ex){Thread.currentThread().interrupt();retry=true;}catch(Exception ex){retry=true;Log.e("SolarAlarm","Daily background GPS failed",ex);prefs.edit().putString("gps_status","Background location error: "+ex.getClass().getSimpleName()).apply();}finally{if(!r.stopped){jobFinished(p,retry);}if(active==r)active=null;}},"solar-alarm-daily-gps");r.thread.start();return true;}
private Location request(LocationManager manager,String provider,long timeout,Run r) throws InterruptedException {if(r.stopped||!manager.isProviderEnabled(provider))return null;CountDownLatch latch=new CountDownLatch(1);AtomicReference<Location> received=new AtomicReference<>();CancellationSignal signal=new CancellationSignal();r.signal=signal;try{manager.getCurrentLocation(provider,signal,getMainExecutor(),fix->{received.set(fix);latch.countDown();});latch.await(timeout,TimeUnit.MILLISECONDS);}catch(SecurityException|IllegalArgumentException ex){Log.w("SolarAlarm","Location provider "+provider+" unavailable",ex);}finally{signal.cancel();if(r.signal==signal)r.signal=null;}if(r.stopped||Thread.currentThread().isInterrupted())return null;Location fix=received.get();long now=System.currentTimeMillis();if(fix==null||fix.getTime()<now-120000L||fix.getTime()>now+120000L)return null;return fix;}
public boolean onStopJob(JobParameters p){Run r=active;if(r!=null){r.stopped=true;CancellationSignal s=r.signal;if(s!=null)s.cancel();if(r.thread!=null)r.thread.interrupt();}return true;}
}
